package store.model;
import java.util.*;
public final class Cart{private final String id;private final Customer customer;private final Map<String,CartItem> items=new LinkedHashMap<>();public Cart(String id,Customer c){this.id=id;customer=c;}public String id(){return id;}public Customer customer(){return customer;}public Collection<CartItem> items(){return Collections.unmodifiableCollection(items.values());}public void add(Product p,int q){if(!p.active())throw new IllegalArgumentException("Inactive product");if(q<=0)throw new IllegalArgumentException("Quantity must be positive");CartItem old=items.get(p.id());items.put(p.id(),new CartItem(p,q+(old==null?0:old.quantity())));}public void update(String pid,int q){if(!items.containsKey(pid)||q<=0)throw new IllegalArgumentException("Invalid cart update");items.put(pid,new CartItem(items.get(pid).product(),q));}public void remove(String pid){items.remove(pid);}public double subtotal(){return items.values().stream().mapToDouble(CartItem::subtotal).sum();}public boolean empty(){return items.isEmpty();}}
